    "blokeak": [
     {
      "mota": "testua",
      "html": "<math display=\"block\"><mrow><msub><mi>A</mi><mrow><mn>8</mn><mtext mathvariant=\"normal\">(i)</mtext></mrow></msub><mo>=</mo><mfrac><mn>4</mn><mn>3</mn></mfrac><mo stretchy=\"false\" form=\"prefix\">(</mo><mi>q</mi><mo>−</mo><mi>p</mi><mo stretchy=\"false\" form=\"postfix\">)</mo><mo stretchy=\"false\" form=\"prefix\">(</mo><mi>s</mi><mo>−</mo><mi>r</mi><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>,</mo><mspace width=\"1.0em\"></mspace><msub><mi>A</mi><mrow><mn>8</mn><mtext mathvariant=\"normal\">(ii)</mtext></mrow></msub><mo>=</mo><mfrac><mrow><msup><mi>a</mi><mn>2</mn></msup><mrow><mi mathvariant=\"normal\">ln</mi><mo>&#8289;</mo></mrow><mn>2</mn></mrow><mn>2</mn></mfrac><mspace width=\"1.0em\"></mspace><mi>✓</mi><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> (Em. ofizialak) </mtext><mspace width=\"0.333em\"></mspace></mrow></mrow></math>"
     }
    ]
