    "mota": "kutxa",
    "kolorea": "laranja",
    "titulua": null,
    "blokeak": [
     {
      "mota": "testua",
      "html": "<math display=\"block\"><mrow><msub><mo>∫</mo><mrow><mi>A</mi><mi>B</mi></mrow></msub><mover><mi>F</mi><mo accent=\"true\">→</mo></mover><mo>⋅</mo><mi>d</mi><mi>s</mi><mo>=</mo><mfrac><mn>1</mn><mn>12</mn></mfrac><mo>−</mo><mfrac><mn>1</mn><mn>16</mn></mfrac><mo>−</mo><mfrac><mn>7</mn><mn>8</mn></mfrac><mspace width=\"1.0em\"></mspace><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> (alde bakarra; iturrian itxi gabe) </mtext><mspace width=\"0.333em\"></mspace></mrow></mrow></math>"
     }
    ]
