     {
      "mota": "testua",
      "html": "<math display=\"block\"><mrow><mi>I</mi><mo>=</mo><mn>60</mn><mi>π</mi><mspace width=\"1.0em\"></mspace><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> (Greenez ETA zuzenean, </mtext><mspace width=\"0.333em\"></mspace></mrow><mspace width=\"0.167em\"></mspace><msub><mi>γ</mi><mn>3</mn></msub><mo>,</mo><msub><mi>γ</mi><mn>4</mn></msub><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> ebaki-segmentuak deuseztatuta) </mtext><mspace width=\"0.333em\"></mspace></mrow></mrow></math>"
     }
