    "blokeak": [
     {
      "mota": "testua",
      "html": "<math display=\"block\"><mrow><msub><mo>∭</mo><mi>W</mi></msub><mi>z</mi><mi>d</mi><mi>V</mi><mo>=</mo><mfrac><mi>π</mi><mn>2</mn></mfrac><mspace width=\"1.0em\"></mspace><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> (hiru metodoz planteatua; zenbakia gurea) </mtext><mspace width=\"0.333em\"></mspace></mrow></mrow></math>"
     }
    ]
