    "mota": "kutxa",
    "kolorea": "laranja",
    "titulua": null,
    "blokeak": [
     {
      "mota": "testua",
      "html": "<math display=\"block\"><mrow><msub><mo>∬</mo><mi>S</mi></msub><mover><mi>F</mi><mo accent=\"true\">→</mo></mover><mspace width=\"0.167em\"></mspace><mover><mi>n</mi><mo accent=\"true\">̂</mo></mover><mo>⋅</mo><mi>d</mi><mi>S</mi><mo>=</mo><mfrac><mrow><mn>13</mn><msqrt><mn>5</mn></msqrt><mspace width=\"0.167em\"></mspace><mi>π</mi></mrow><mn>3</mn></mfrac></mrow></math>"
     }
    ]
