    "elementuak": [
     "<math display=\"inline\"><mrow><msup><mrow><mo stretchy=\"true\" form=\"prefix\">|</mo><mi>z</mi><mo>+</mo><mi>w</mi><mo stretchy=\"true\" form=\"postfix\">|</mo></mrow><mn>2</mn></msup><mo>+</mo><msup><mrow><mo stretchy=\"true\" form=\"prefix\">|</mo><mi>z</mi><mo>−</mo><mi>w</mi><mo stretchy=\"true\" form=\"postfix\">|</mo></mrow><mn>2</mn></msup><mo>=</mo><mn>2</mn><mo stretchy=\"false\" form=\"prefix\">|</mo><mi>z</mi><msup><mo stretchy=\"false\" form=\"prefix\">|</mo><mn>2</mn></msup><mo>+</mo><mn>2</mn><mo stretchy=\"false\" form=\"prefix\">|</mo><mi>w</mi><msup><mo stretchy=\"false\" form=\"prefix\">|</mo><mn>2</mn></msup></mrow></math>.",
     "<math display=\"inline\"><mrow><msup><mrow><mo stretchy=\"true\" form=\"prefix\">|</mo><mi>z</mi><mover><mi>w</mi><mo accent=\"true\">¯</mo></mover><mo>+</mo><mn>1</mn><mo stretchy=\"true\" form=\"postfix\">|</mo></mrow><mn>2</mn></msup><mo>+</mo><msup><mrow><mo stretchy=\"true\" form=\"prefix\">|</mo><mi>z</mi><mo>−</mo><mi>w</mi><mo stretchy=\"true\" form=\"postfix\">|</mo></mrow><mn>2</mn></msup><mo>=</mo><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>1</mn><mo>+</mo><mo stretchy=\"false\" form=\"prefix\">|</mo><mi>z</mi><msup><mo stretchy=\"false\" form=\"prefix\">|</mo><mn>2</mn></msup><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mn>1</mn><mo>+</mo><mo stretchy=\"false\" form=\"prefix\">|</mo><mi>w</mi><msup><mo stretchy=\"false\" form=\"prefix\">|</mo><mn>2</mn></msup><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow></mrow></math>.",
     "<math display=\"inline\"><mrow><msup><mrow><mo stretchy=\"true\" form=\"prefix\">|</mo><mi>z</mi><mover><mi>w</mi><mo accent=\"true\">¯</mo></mover><mo>−</mo><mn>1</mn><mo stretchy=\"true\" form=\"postfix\">|</mo></mrow><mn>2</mn></msup><mo>−</mo><msup><mrow><mo stretchy=\"true\" form=\"prefix\">|</mo><mi>z</mi><mo>−</mo><mi>w</mi><mo stretchy=\"true\" form=\"postfix\">|</mo></mrow><mn>2</mn></msup><mo>=</mo><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mo stretchy=\"false\" form=\"prefix\">|</mo><mi>z</mi><msup><mo stretchy=\"false\" form=\"prefix\">|</mo><mn>2</mn></msup><mo>−</mo><mn>1</mn><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mo stretchy=\"false\" form=\"prefix\">|</mo><mi>w</mi><msup><mo stretchy=\"false\" form=\"prefix\">|</mo><mn>2</mn></msup><mo>−</mo><mn>1</mn><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow></mrow></math>."
    ]
