  "blokeak": [
   {
    "mota": "testua",
    "html": "<strong>16.</strong> Representa gráficamente en el plano complejo los conjuntos definidos por las siguientes igualdades y desigualdades:"
   },
   {
    "mota": "zerrenda",
    "ordenatua": true,
    "elementuak": [
     "<math display=\"inline\"><mrow><mrow><mo stretchy=\"true\" form=\"prefix\">|</mo><mi>z</mi><mo>−</mo><mn>1</mn><mo>−</mo><mi>i</mi><mo stretchy=\"true\" form=\"postfix\">|</mo></mrow><mo>=</mo><mn>1</mn></mrow></math>",
     "<math display=\"inline\"><mrow><mrow><mo stretchy=\"true\" form=\"prefix\">|</mo><mi>z</mi><mo>−</mo><mn>1</mn><mo stretchy=\"true\" form=\"postfix\">|</mo></mrow><mo>=</mo><mrow><mo stretchy=\"true\" form=\"prefix\">|</mo><mi>z</mi><mo>+</mo><mi>i</mi><mo stretchy=\"true\" form=\"postfix\">|</mo></mrow></mrow></math>",
     "<math display=\"inline\"><mrow><mrow><mo stretchy=\"true\" form=\"prefix\">|</mo><mi>z</mi><mo>−</mo><mn>1</mn><mo>+</mo><mi>i</mi><mo stretchy=\"true\" form=\"postfix\">|</mo></mrow><mo>≥</mo><mrow><mo stretchy=\"true\" form=\"prefix\">|</mo><mi>z</mi><mo>−</mo><mn>1</mn><mo>−</mo><mi>i</mi><mo stretchy=\"true\" form=\"postfix\">|</mo></mrow></mrow></math>",
     "<math display=\"inline\"><mrow><mrow><mo stretchy=\"true\" form=\"prefix\">|</mo><mi>z</mi><mo>+</mo><mn>4</mn><mi>i</mi><mo stretchy=\"true\" form=\"postfix\">|</mo></mrow><mo>+</mo><mrow><mo stretchy=\"true\" form=\"prefix\">|</mo><mi>z</mi><mo>−</mo><mn>4</mn><mi>i</mi><mo stretchy=\"true\" form=\"postfix\">|</mo></mrow><mo>=</mo><mn>10</mn></mrow></math>",
     "<math display=\"inline\"><mrow><mrow><mo stretchy=\"true\" form=\"prefix\">|</mo><mi>z</mi><mo>−</mo><mn>2</mn><mo>+</mo><mi>i</mi><mo stretchy=\"true\" form=\"postfix\">|</mo></mrow><mo>≤</mo><mn>1</mn></mrow></math>",
     "<math display=\"inline\"><mrow><mrow><mo stretchy=\"true\" form=\"prefix\">|</mo><mn>2</mn><mi>z</mi><mo>+</mo><mn>3</mn><mo stretchy=\"true\" form=\"postfix\">|</mo></mrow><mo>&gt;</mo><mn>4</mn></mrow></math>",
     "<math display=\"inline\"><mrow><mi>z</mi><mover><mi>z</mi><mo accent=\"true\">¯</mo></mover><mo>=</mo><mn>36</mn></mrow></math>",
     "<math display=\"inline\"><mrow><mrow><mo stretchy=\"true\" form=\"prefix\">|</mo><mi>z</mi><mo>−</mo><mn>4</mn><mo stretchy=\"true\" form=\"postfix\">|</mo></mrow><mo>≥</mo><mo stretchy=\"false\" form=\"prefix\">|</mo><mi>z</mi><mo stretchy=\"false\" form=\"prefix\">|</mo></mrow></math>",
     "<math display=\"inline\"><mrow><mrow><mtext mathvariant=\"normal\">Im </mtext><mspace width=\"0.333em\"></mspace></mrow><mi>z</mi><mo>=</mo><mn>1</mn></mrow></math>",
     "<math display=\"inline\"><mrow><mi>−</mi><mi>π</mi><mo>&lt;</mo><mrow><mi mathvariant=\"normal\">arg</mi><mo>&#8289;</mo></mrow><mi>z</mi><mo>≤</mo><mi>π</mi><mo>,</mo><mspace width=\"1.0em\"></mspace><mo stretchy=\"false\" form=\"prefix\">|</mo><mi>z</mi><mo stretchy=\"false\" form=\"prefix\">|</mo><mo>≥</mo><mn>2</mn></mrow></math>",
     "<math display=\"inline\"><mrow><mrow><mtext mathvariant=\"normal\">Im </mtext><mspace width=\"0.333em\"></mspace></mrow><mi>z</mi><mo>&gt;</mo><mn>1</mn></mrow></math>",
     "<math display=\"inline\"><mrow><mtext mathvariant=\"normal\">Re</mtext><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><mfrac><mn>1</mn><mi>z</mi></mfrac><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>≤</mo><mfrac><mn>1</mn><mn>2</mn></mfrac></mrow></math>",
     "<math display=\"inline\"><mrow><mtext mathvariant=\"normal\">Re</mtext><mrow><mo stretchy=\"true\" form=\"prefix\">(</mo><msup><mi>z</mi><mn>2</mn></msup><mo stretchy=\"true\" form=\"postfix\">)</mo></mrow><mo>&gt;</mo><mn>0</mn></mrow></math>",
     "<math display=\"inline\"><mrow><mo stretchy=\"false\" form=\"prefix\">|</mo><mi>z</mi><mo stretchy=\"false\" form=\"prefix\">|</mo><mo>=</mo><mn>2</mn><mrow><mi mathvariant=\"normal\">cos</mi><mo>&#8289;</mo></mrow><mo stretchy=\"false\" form=\"prefix\">(</mo><mrow><mi mathvariant=\"normal\">arg</mi><mo>&#8289;</mo></mrow><mi>z</mi><mo stretchy=\"false\" form=\"postfix\">)</mo></mrow></math>",
     "<math display=\"inline\"><mrow><mn>0</mn><mo>≤</mo><mrow><mi mathvariant=\"normal\">arg</mi><mo>&#8289;</mo></mrow><mi>z</mi><mo>≤</mo><mi>π</mi><mi>/</mi><mn>4</mn></mrow></math>",
     "<math display=\"inline\"><mrow><mover><mi>z</mi><mo accent=\"true\">¯</mo></mover><mo>=</mo><msup><mi>z</mi><mrow><mi>−</mi><mn>1</mn></mrow></msup></mrow></math>",
     "<math display=\"inline\"><mrow><mi>z</mi><mo>+</mo><mover><mi>z</mi><mo accent=\"true\">¯</mo></mover><mo>=</mo><mn>1</mn></mrow></math>",
     "<math display=\"inline\"><mrow><mrow><mo stretchy=\"true\" form=\"prefix\">|</mo><mi>z</mi><mo>−</mo><mn>1</mn><mo stretchy=\"true\" form=\"postfix\">|</mo></mrow><mo>=</mo><mn>1</mn></mrow></math>"
    ]
   }
  ],
